<script setup lang="ts">
import { computed } from 'vue'
import { useAppStore } from '../../stores/appStore'
const { currentUser, students, programmes, sessions, semesters, subjects, marksEntries, semesterResults, navigate } = useAppStore()
const student = computed(() => students.value.find(item => item.email.toLowerCase() === currentUser.value?.email.toLowerCase()))
const programme = computed(() => programmes.value.find(item => item.id === student.value?.programmeId))
const session = computed(() => sessions.value.find(item => item.id === student.value?.sessionId))
const semester = computed(() => semesters.value.find(item => item.programmeId === student.value?.programmeId && item.sessionId === student.value?.sessionId && item.number === student.value?.currentSemester))
const courses = computed(() => subjects.value.filter(item => item.programmeId === student.value?.programmeId && item.semesterNumber === student.value?.currentSemester))
const publishedResults = computed(() => semesterResults.value.filter(result => result.studentId === student.value?.id && result.publicationStatus === 'published'))
const latestResult = computed(() => publishedResults.value[publishedResults.value.length - 1])
const recentEntries = computed(() => marksEntries.value.filter(entry => entry.studentId === student.value?.id).slice(-5).reverse())
const stats = computed(() => [['Current Semester', semester.value?.name ?? 'Not configured'], ['Registered Courses', courses.value.length], ['Published Results', publishedResults.value.length], ['Current GPA', latestResult.value ? latestResult.value.gpa.toFixed(2) : 'Not Available'], ['CGPA', latestResult.value ? latestResult.value.cgpa.toFixed(2) : 'Not Available']])
</script>
<template>
  <div v-if="student" class="space-y-6"><section class="rounded-xl bg-navy-800 p-6 text-white"><p class="text-xs font-medium uppercase tracking-[0.18em] text-gold-300">Student Portal</p><h2 class="mt-1 font-serif text-2xl font-bold">Welcome back, {{ student.name }}</h2><p class="mt-1 text-sm text-navy-300">{{ student.studentId }} · {{ programme?.name }}</p><p class="mt-1 text-xs text-navy-400">{{ session?.name }} · {{ semester?.name ?? `Semester ${student.currentSemester}` }}</p></section><section class="grid grid-cols-2 gap-3 lg:grid-cols-5"><div v-for="stat in stats" :key="stat[0]" class="rounded-xl border border-navy-100 bg-white p-4"><div class="text-xl font-serif font-bold text-navy-900">{{ stat[1] }}</div><div class="mt-1 text-xs text-navy-500">{{ stat[0] }}</div></div></section><section class="grid grid-cols-1 gap-6 xl:grid-cols-3"><div class="rounded-xl border border-navy-100 bg-white p-5 xl:col-span-2"><div class="mb-4 flex items-center justify-between"><div><h3 class="font-serif font-semibold text-navy-900">Current Semester Courses</h3><p class="text-xs text-navy-400">{{ courses.length }} registered courses</p></div><button class="text-xs text-navy-500" @click="navigate('student-courses')">View all →</button></div><div class="overflow-x-auto"><table class="w-full min-w-155 text-sm"><thead><tr class="border-b border-navy-100 text-left text-xs uppercase text-navy-500"><th class="px-3 py-3">Code</th><th class="px-3 py-3">Course Title</th><th class="px-3 py-3">Credits</th><th class="px-3 py-3">Status</th></tr></thead><tbody class="divide-y divide-navy-50"><tr v-for="course in courses" :key="course.id"><td class="px-3 py-3 font-mono text-xs">{{ course.code }}</td><td class="px-3 py-3 text-navy-800">{{ course.title }}</td><td class="px-3 py-3">{{ course.credits }}</td><td class="px-3 py-3"><span class="rounded-full bg-blue-50 px-2 py-0.5 text-xs text-blue-700">Registered</span></td></tr></tbody></table><div v-if="!courses.length" class="p-8 text-center text-sm text-navy-400">No current courses available.</div></div></div><div class="rounded-xl border border-navy-100 bg-white p-5"><h3 class="font-serif font-semibold text-navy-900">Academic Progress</h3><div class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><span class="text-navy-500">Programme</span><span class="max-w-[60%] text-right font-medium text-navy-800">{{ programme?.name }}</span></div><div class="flex justify-between"><span class="text-navy-500">Session</span><span class="font-medium text-navy-800">{{ session?.name }}</span></div><div class="flex justify-between"><span class="text-navy-500">Semester</span><span class="font-medium text-navy-800">{{ semester?.name ?? 'Not configured' }}</span></div><div class="flex justify-between"><span class="text-navy-500">Status</span><span class="rounded-full bg-emerald-50 px-2 py-0.5 text-xs text-emerald-700">{{ student.status }}</span></div></div></div></section><section class="rounded-xl border border-navy-100 bg-white p-5"><div class="mb-4 flex items-center justify-between"><div><h3 class="font-serif font-semibold text-navy-900">Recent Published Results</h3><p class="text-xs text-navy-400">Only your published academic results are shown.</p></div><button class="text-xs text-navy-500" @click="navigate('student-results')">View results →</button></div><div v-if="recentEntries.length" class="grid gap-2 md:grid-cols-2 xl:grid-cols-4"><div v-for="entry in recentEntries" :key="entry.id" class="rounded-lg bg-navy-50 p-3"><div class="font-mono text-xs text-navy-500">{{ subjects.find(subject => subject.id === entry.subjectId)?.code }}</div><div class="mt-1 font-medium text-navy-800">{{ entry.grade }}</div><div class="text-xs text-navy-500">{{ entry.totalMarks }} marks · {{ entry.gradePoint.toFixed(1) }} points</div></div></div><div v-else class="py-8 text-center text-sm text-navy-400">No published course results available yet.</div></section></div><div v-else class="rounded-xl border border-amber-200 bg-amber-50 p-6 text-sm text-amber-800">Your student account is not linked to a student record yet. Contact the examination office.</div>
</template>
